/**
 * Billing period arithmetic: period ends, full-period charges and proration.
 * All calendar maths is UTC.
 */
import { getPlanLimits } from "@/config/plan-limits";
import { toIsoTimestamp } from "@/types/common";
import type { BillingInterval, PlanId } from "@/types/billing";
import type { IsoTimestamp } from "@/types/common";

const DAY_MS = 24 * 60 * 60 * 1000;

export function monthsIn(interval: BillingInterval): number {
  return interval === "annual" ? 12 : 1;
}

/** Adds calendar months, clamping to the target month's last day. */
export function addMonths(date: Date, months: number): Date {
  const total = date.getUTCMonth() + months;
  const year = date.getUTCFullYear() + Math.floor(total / 12);
  const month = ((total % 12) + 12) % 12;
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const result = new Date(date.getTime());
  result.setUTCFullYear(year, month, Math.min(date.getUTCDate(), lastDay));
  return result;
}

export function periodEnd(start: Date, interval: BillingInterval): Date {
  return addMonths(start, monthsIn(interval));
}

/** Full charge of one period, in cents. */
export function fullPeriodCharge(
  plan: PlanId,
  seats: number,
  interval: BillingInterval,
): number {
  return (
    getPlanLimits(plan).priceCentsPerSeatMonthly * seats * monthsIn(interval)
  );
}

/** Scales `fullCents` by days left over days in the period, rounded down. */
export function prorate(
  fullCents: number,
  periodStart: IsoTimestamp,
  periodEndStamp: IsoTimestamp,
  now: Date,
): number {
  const start = new Date(periodStart).getTime();
  const end = new Date(periodEndStamp).getTime();
  const days = Math.max(1, Math.round((end - start) / DAY_MS));
  const left =
    now.getTime() >= end
      ? 0
      : Math.min(days, Math.ceil((end - now.getTime()) / DAY_MS));
  return Math.floor((fullCents * left) / days);
}

export function stamp(date: Date): IsoTimestamp {
  return toIsoTimestamp(date);
}
EOF
