/** Every subscription of a live (non-archived) workspace; used by the renewal job. */
export async function listSubscriptionsOfLiveOrgs(): Promise<
  readonly Subscription[]
> {
  const rows = getDb()
    .select({ subscription: subscriptions })
    .from(subscriptions)
    .innerJoin(organizations, eq(organizations.id, subscriptions.orgId))
    .where(isNull(organizations.archivedAt))
    .all();

  return rows.map((row) => toSubscription(row.subscription));
}

export type PeriodPatch = {
  plan?: PlanId;
  interval?: BillingInterval;
  status?: Subscription["status"];
  cancelAt?: IsoTimestamp | null;
  currentPeriodStart: IsoTimestamp;
  currentPeriodEnd: IsoTimestamp;
};

/**
 * Moves the period on. Compare-and-set on the period end the caller saw, so a
 * concurrent or repeated run cannot apply the same step twice; returns `null`
 * when the row has already moved.
 */
export async function setPeriod(
  orgId: OrgId,
  expectedPeriodEnd: IsoTimestamp,
  patch: PeriodPatch,
): Promise<Subscription | null> {
  const row = getDb()
    .update(subscriptions)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(subscriptions.orgId, orgId),
        eq(subscriptions.currentPeriodEnd, expectedPeriodEnd),
      ),
    )
    .returning()
    .get();
  return row ? toSubscription(row) : null;
}
