/** Next free invoice number within the workspace (`INV-0001`, `INV-0002`, ...). */
export async function nextInvoiceNumber(orgId: OrgId): Promise<string> {
  const rows = getDb()
    .select({ number: invoices.number })
    .from(invoices)
    .where(orgPredicate(invoices.orgId, orgId))
    .all();
  let max = 0;
  for (const { number } of rows) {
    const match = /^INV-(\\d+)$/.exec(number);
    if (match) max = Math.max(max, Number(match[1]));
  }
  return `INV-${String(max + 1).padStart(4, "0")}`;
}
