/**
 * Renews subscriptions period by period, invoices paid periods and ends
 * cancelled subscriptions on their cancellation date.
 *
 * Must call (do not reimplement): emit, issueInvoice
 */
import { fullPeriodCharge, periodEnd } from "@/lib/billing-period";
import { emit } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import { issueInvoice } from "@/server/services/billing-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Subscription } from "@/types/billing";

const logger = createLogger("billing-renewal-job");

export async function runBillingRenewalJob(now: Date): Promise<JobResult> {
  return runJob("billing-renewal", async (result) => {
    const subscriptions = await subscriptionRepo.listSubscriptionsOfLiveOrgs();

    for (const subscription of subscriptions) {
      try {
        const changed =
          subscription.status === "active"
            ? await renew(subscription, now)
            : subscription.status === "canceled"
              ? await endCancelled(subscription, now)
              : false;
        if (changed) result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("billing renewal failed", {
          orgId: subscription.orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

async function renew(subscription: Subscription, now: Date): Promise<boolean> {
  let current = subscription;
  let moved = false;

  while (new Date(current.currentPeriodEnd).getTime() <= now.getTime()) {
    const start = new Date(current.currentPeriodEnd);
    const end = toIsoTimestamp(periodEnd(start, current.interval));
    const next = await subscriptionRepo.setPeriod(
      current.orgId,
      current.currentPeriodEnd,
      { currentPeriodStart: current.currentPeriodEnd, currentPeriodEnd: end },
    );
    if (!next) return moved;
    moved = true;

    if (current.plan !== "free") {
      await issueInvoice(
        current.orgId,
        fullPeriodCharge(current.plan, current.seats, current.interval),
        next.currentPeriodStart,
        next.currentPeriodEnd,
        now,
      );
    }
    current = next;
  }

  return moved;
}

async function endCancelled(
  subscription: Subscription,
  now: Date,
): Promise<boolean> {
  if (subscription.cancelAt === null) return false;
  const cancelAt = new Date(subscription.cancelAt);
  if (cancelAt.getTime() > now.getTime()) return false;

  const next = await subscriptionRepo.setPeriod(
    subscription.orgId,
    subscription.currentPeriodEnd,
    {
      plan: "free",
      interval: "monthly",
      status: "active",
      cancelAt: null,
      currentPeriodStart: subscription.cancelAt,
      currentPeriodEnd: toIsoTimestamp(periodEnd(cancelAt, "monthly")),
    },
  );
  if (!next) return false;

  if (subscription.plan !== "free") {
    await emit("billing.plan_changed", {
      orgId: subscription.orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(now),
      from: subscription.plan,
      to: "free",
    });
  }
  return true;
}
